import React, { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Building2, MapPin, Calendar, ArrowRight, CheckCircle2 } from 'lucide-react';

const OfferDetails = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  
  // حالة لمتابعة ما إذا كان الطالب قد قدم على هذا العرض أم لا
  const [hasApplied, setHasApplied] = useState(false);

  const offerData = {
    title: "مطور ويب React",
    company: "Tech Solutions",
    location: "قسنطينة",
    description: "نحن نبحث عن متربص شغوف بتعلم تطوير الواجهات الأمامية باستخدام React و Tailwind CSS. ستعمل مع فريقنا على بناء واجهات مستخدم حديثة وتفاعلية.",
    duration: "3 أشهر",
    postedAt: "منذ يومين"
  };

  // الدالة المسؤولة عن تشغيل زر التقديم
  const handleApply = () => {
    // إظهار نافذة تأكيد للمستخدم!!
    const confirmApply = window.confirm(` تريد تأكيد التقديم على عرض هل${offerData.title}`);
    
    if (confirmApply) {
      setHasApplied(true);
      alert(` إرسال طلبك بنجاح للعرض رقم: ${id}. يمكنك متابعة الحالة من صفحة "طلباتي".`);
      
      // مستقبلاً: axios.post('/api/applications/', { offer: id })
    }
  };

  return (
    <div className="max-w-4xl mx-auto p-6" dir="rtl">
      {/* زر العودة */}
      <button 
        onClick={() => navigate(-1)} 
        className="flex items-center gap-2 text-slate-500 hover:text-blue-600 mb-6 transition-colors font-bold"
      >
        <ArrowRight size={20} /> العودة للعروض
      </button>

      <div className="bg-white rounded-3xl p-8 shadow-sm border border-slate-100 overflow-hidden">
        {/* رأس الصفحة */}
        <div className="flex items-start justify-between mb-8">
          <div className="flex gap-5">
            <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center shadow-inner">
              <Building2 size={32} />
            </div>
            <div>
              <h1 className="text-2xl font-black text-slate-900">{offerData.title}</h1>
              <p className="text-blue-600 font-bold text-lg">{offerData.company}</p>
            </div>
          </div>
          {hasApplied && (
            <span className="bg-green-50 text-green-600 px-4 py-2 rounded-full text-sm font-bold flex items-center gap-2 border border-green-100">
              <CheckCircle2 size={16} /> تم التقديم
            </span>
          )}
        </div>

        {/* المعلومات الأساسية */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-8">
          <div className="flex items-center gap-3 text-slate-600 bg-slate-50 p-4 rounded-2xl border border-transparent hover:border-slate-200 transition-all">
            <MapPin size={20} className="text-blue-500" />
            <span className="font-medium">{offerData.location}</span>
          </div>
          <div className="flex items-center gap-3 text-slate-600 bg-slate-50 p-4 rounded-2xl border border-transparent hover:border-slate-200 transition-all">
            <Calendar size={20} className="text-blue-500" />
            <span className="font-medium">المدة: {offerData.duration}</span>
          </div>
        </div>

        {/* وصف العرض */}
        <div className="space-y-4 mb-10">
          <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
            <div className="w-2 h-6 bg-blue-600 rounded-full"></div>
            وصف التربص
          </h2>
          <p className="text-slate-600 leading-relaxed text-lg italic">
            "{offerData.description}"
          </p>
        </div>

        {/* زر التقديم التفاعلي */}
        {!hasApplied ? (
          <button 
            onClick={handleApply}
            className="w-full py-4 bg-blue-600 text-white rounded-2xl font-bold text-lg hover:bg-blue-700 shadow-lg shadow-blue-100 transform active:scale-[0.98] transition-all"
            >
            تقديم الطلب الآن
          </button>
        ) : (
          <button 
            disabled
            className="w-full py-4 bg-slate-100 text-slate-400 rounded-2xl font-bold text-lg cursor-not-allowed"
          >
            لقد تقدمت لهذا العرض مسبقاً
          </button>
        )}
      </div>
    </div>
  );
};

export default OfferDetails;
